"""Read/write the store-agnostic vector artifact (a single parquet file).

Shared by the CI build script (writes embedded chunk rows) and the serving-side
ingest (reads them back into the vector store). The artifact is self-contained:
chunk vectors + metadata columns, with the build config (embed model/dim,
corpus_version, counts) stored in the parquet schema metadata under
:data:`META_KEY`. Keeping read and write together makes the on-disk contract one
source of truth — neither side hard-codes column names independently.

:func:`write_manifest` produces the sibling ``manifest.json`` used for S3
upload and Docker image bakes (checksum + commit for cache busting).
"""

import hashlib
import json
from pathlib import Path
from typing import Any, Dict, List, Tuple

import numpy as np
import pyarrow as pa
import pyarrow.parquet as pq

# Schema-metadata key under which the build config is stored in the parquet
# footer; the serving-side ingest reads this to assert model/chunking parity.
META_KEY = "rasa_retrieval_meta"

# String metadata columns carried per chunk, besides ``vector`` / ``chunk_index``.
_STRING_COLUMNS = ("text", "doc_id", "url", "title", "topic", "version")

_SHA256_CHUNK_SIZE = 1024 * 1024


def write_vectors_parquet(
    rows: List[Dict[str, Any]], meta: Dict[str, Any], output_path: Path
) -> None:
    """Write embedded chunk rows + build metadata to one parquet file."""
    dim = len(rows[0]["vector"])
    matrix = np.vstack([np.asarray(r["vector"], dtype=np.float32) for r in rows])
    vector_values = pa.array(matrix.reshape(-1), type=pa.float32())

    columns: Dict[str, pa.Array] = {
        "vector": pa.FixedSizeListArray.from_arrays(vector_values, dim)
    }
    for name in _STRING_COLUMNS:
        columns[name] = pa.array([r[name] for r in rows], pa.string())
    columns["chunk_index"] = pa.array([r["chunk_index"] for r in rows], pa.int32())

    table = pa.table(columns)
    # Self-contained artifact: stash the build config in the parquet footer.
    table = table.replace_schema_metadata({META_KEY: json.dumps(meta)})

    output_path.parent.mkdir(parents=True, exist_ok=True)
    pq.write_table(table, str(output_path))


def read_vectors_parquet(
    path: Path,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Read an artifact back into ``(rows, meta)``.

    Rows match the shape :meth:`BaseVectorStore.add` expects (``vector`` as a
    float32 ndarray plus metadata fields); ``meta`` is the build config from the
    parquet footer.
    """
    table = pq.read_table(str(path))
    raw_meta = (table.schema.metadata or {}).get(META_KEY.encode())
    if raw_meta is None:
        raise ValueError(
            f"Parquet artifact at {path} is missing '{META_KEY}' schema metadata."
        )
    meta = json.loads(raw_meta)

    data = table.to_pydict()
    vectors = data["vector"]
    rows: List[Dict[str, Any]] = []
    for i in range(table.num_rows):
        row: Dict[str, Any] = {"vector": np.asarray(vectors[i], dtype=np.float32)}
        for name in _STRING_COLUMNS:
            row[name] = data[name][i]
        row["chunk_index"] = data["chunk_index"][i]
        rows.append(row)
    return rows, meta


def _read_parquet_meta(path: Path) -> Dict[str, Any]:
    """Read build metadata from a vector parquet footer without loading rows."""
    parquet_file = pq.ParquetFile(str(path))
    raw_meta = (parquet_file.schema_arrow.metadata or {}).get(META_KEY.encode())
    if raw_meta is None:
        raise ValueError(
            f"Parquet artifact at {path} is missing '{META_KEY}' schema metadata."
        )
    return json.loads(raw_meta)


def _sha256_file(path: Path) -> str:
    """Return the SHA-256 hex digest of a file, reading in fixed-size chunks."""
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while chunk := handle.read(_SHA256_CHUNK_SIZE):
            digest.update(chunk)
    return digest.hexdigest()


def write_manifest(
    parquet_path: Path, manifest_path: Path | None = None
) -> Dict[str, Any]:
    """Write ``manifest.json`` for a vector parquet artifact.

    The manifest mirrors parquet footer metadata and adds distribution fields
    (``docs_commit``, ``parquet_sha256``) consumed by S3 upload and Docker
    builds.
    """
    parquet_path = parquet_path.resolve()
    if manifest_path is None:
        manifest_path = parquet_path.with_name("manifest.json")
    else:
        manifest_path = manifest_path.resolve()

    meta = _read_parquet_meta(parquet_path)
    corpus_version = meta.get("corpus_version")
    if not corpus_version:
        raise ValueError(
            f"Parquet at {parquet_path} is missing 'corpus_version' in metadata."
        )

    manifest: Dict[str, Any] = {
        **meta,
        "docs_commit": corpus_version,
        "parquet_sha256": _sha256_file(parquet_path),
    }
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest_path.write_text(json.dumps(manifest, indent=2) + "\n")
    return manifest
